import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiLevel","description":"","frontmatter":{},"headers":[],"relativePath":"modules/level/index.md","filePath":"modules/level/index.md","lastUpdated":0}`),a={name:`modules/level/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakilevel" tabindex="-1">EmakiLevel <a class="header-anchor" href="#emakilevel" aria-label="Permalink to “EmakiLevel”">​</a></h1><p>EmakiLevel 是 Emaki 系列的等级与多经验类型插件。它负责把长期成长从原版经验中独立出来，管理主等级、战斗、挖矿、钓鱼、合成、炼药、冶炼、驯养等多个成长线，并把经验来源、升级需求、升级奖励、属性贡献、PlaceholderAPI、CoreLib Action 和 MythicMobs Drop 统一到一个插件中。</p><h2 id="模块信息" tabindex="-1">模块信息 <a class="header-anchor" href="#模块信息" aria-label="Permalink to “模块信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>当前值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>1.6.0</code></td></tr><tr><td>插件本体</td><td><code>EmakiLevel-1.6.0.jar</code></td></tr><tr><td>开发者 API</td><td><code>emaki-level-api-1.6.0.jar</code></td></tr><tr><td>主类</td><td><code>emaki.jiuwu.craft.level.EmakiLevelPlugin</code></td></tr><tr><td>主命令</td><td><code>/emakilevel</code></td></tr><tr><td>别名</td><td><code>/elv</code>、<code>/elevel</code></td></tr><tr><td>硬依赖</td><td><code>EmakiCoreLib</code></td></tr><tr><td>软依赖</td><td><code>MythicMobs</code>、<code>EmakiAttribute</code>、<code>EmakiCooking</code>、<code>EmakiForge</code>、<code>PlaceholderAPI</code></td></tr><tr><td>主要权限</td><td><code>emakilevel.use</code>（默认 true）、<code>emakilevel.levelup</code>（true）、<code>emakilevel.top</code>（true）、<code>emakilevel.reload</code>（op）、<code>emakilevel.debug</code>（op）、<code>emakilevel.admin</code>（op）</td></tr><tr><td>数据存储</td><td><code>plugins/EmakiLevel/data/&lt;uuid&gt;.yml</code></td></tr><tr><td>Java / 平台</td><td>编译基线 Java 25；<code>api-version: 1.21.8</code>；<code>folia-supported: true</code></td></tr></tbody></table><h2 id="安装方式" tabindex="-1">安装方式 <a class="header-anchor" href="#安装方式" aria-label="Permalink to “安装方式”">​</a></h2><p>服务器只需要安装运行时插件本体：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/</span></span>
<span class="line"><span>├─ EmakiCoreLib-*.jar</span></span>
<span class="line"><span>└─ EmakiLevel-1.6.0.jar</span></span></code></pre></div><p>不要把 <code>emaki-level-api-*.jar</code> 放进服务器 <code>plugins/</code> 目录。API Jar 只给第三方开发者作为 Maven <code>provided</code> 或 Gradle <code>compileOnly</code> 编译依赖使用；<code>EmakiLevel</code> 插件本体在打包时已经 shade 了自己的 API。</p><p>可选插件按需安装：</p><table tabindex="0"><thead><tr><th>可选插件</th><th>安装后启用的能力</th></tr></thead><tbody><tr><td>PlaceholderAPI</td><td>注册 <code>%emakilevel_*%</code> 占位符。</td></tr><tr><td>MythicMobs</td><td>读取 MythicMob 击杀来源，并注册 <code>emakilevel_exp</code> / <code>elv_exp</code> 非实物 Drop。</td></tr><tr><td>EmakiAttribute</td><td>把等级类型中的 <code>attributes.values</code> 转为 Attribute 属性贡献。</td></tr><tr><td>EmakiCooking / EmakiForge</td><td>可通过 CoreLib Action 在配方、工艺或流程结果中给玩家等级经验。</td></tr></tbody></table><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to “核心能力”">​</a></h2><ul><li><strong>多等级类型</strong>：每个 <code>types/*.yml</code> 文件定义一个等级类型，默认包含 <code>main</code>、<code>combat</code>、<code>mining</code>、<code>fishing</code>、<code>crafting</code>、<code>brewing</code>、<code>smelting</code>、<code>taming</code> 等类型。</li><li><strong>独立玩家数据</strong>：每名玩家一个 YAML 数据文件，保存每个等级类型的 <code>level</code>、<code>exp</code>、<code>total_exp</code> 与更新时间。</li><li><strong>分层升级需求</strong>：升级所需经验按“类型覆写 → 分组 → 全局”的顺序解析，既支持精确等级值，也支持公式。</li><li><strong>自动/手动升级</strong>：类型可以独立控制自动升级、手动 <code>/elv levelup</code>、经济消耗、材料消耗、升级奖励和升级动作。</li><li><strong>经验来源监听</strong>：支持原版击杀、MythicMobs 击杀、方块破坏、成熟作物收获、钓鱼、合成、炼药、冶炼提取和驯养。</li><li><strong>防刷机制</strong>：可记录玩家放置方块，避免“放置再破坏”刷经验；战斗来源可记录最近造成伤害的玩家。</li><li><strong>CoreLib Action</strong>：其他 Emaki 插件或第三方系统可以通过动作增减经验或等级。</li><li><strong>PDC 同步</strong>：在线玩家实体会同步当前等级、经验、总经验、需求经验和进度，方便其他插件读取。</li><li><strong>属性贡献</strong>：安装 EmakiAttribute 后，可把等级公式计算出的数值注册为属性贡献。</li></ul><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to “默认配置目录”">​</a></h2><p>首次启动会通过 CoreLib Bootstrap 释放默认资源。运行目录结构如下：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiLevel/</span></span>
<span class="line"><span>├─ config.yml                 # 主配置：语言、PDC、属性桥接、MythicMobs、防刷、GUI</span></span>
<span class="line"><span>├─ requirements.yml           # 升级经验需求：全局、分组、精确等级值和公式</span></span>
<span class="line"><span>├─ types/                     # 等级类型定义</span></span>
<span class="line"><span>│  ├─ main.yml</span></span>
<span class="line"><span>│  ├─ combat.yml</span></span>
<span class="line"><span>│  ├─ mining.yml</span></span>
<span class="line"><span>│  └─ ...</span></span>
<span class="line"><span>├─ sources/                   # 经验来源规则</span></span>
<span class="line"><span>│  ├─ combat.yml</span></span>
<span class="line"><span>│  ├─ block_actions.yml</span></span>
<span class="line"><span>│  ├─ mythicmobs.yml</span></span>
<span class="line"><span>│  └─ ...</span></span>
<span class="line"><span>├─ gui/</span></span>
<span class="line"><span>│  ├─ level_gui.yml           # 默认等级 GUI 模板</span></span>
<span class="line"><span>│  └─ top_gui.yml             # 默认排行榜 GUI 模板</span></span>
<span class="line"><span>├─ lang/</span></span>
<span class="line"><span>│  ├─ zh_CN.yml</span></span>
<span class="line"><span>│  └─ en_US.yml</span></span>
<span class="line"><span>└─ data/</span></span>
<span class="line"><span>   └─ &lt;uuid&gt;.yml              # 玩家等级数据</span></span></code></pre></div><p><code>config.yml</code> 中的 <code>release_default_data: true</code> 用于控制缺失默认数据文件时是否释放内置 <code>requirements.yml</code>、<code>types/</code>、<code>sources/</code> 和 <code>gui/</code> 文件。服主已经自定义过的文件不会因为普通重启而被直接覆盖。</p><h2 id="默认等级类型" tabindex="-1">默认等级类型 <a class="header-anchor" href="#默认等级类型" aria-label="Permalink to “默认等级类型”">​</a></h2><table tabindex="0"><thead><tr><th>类型 ID</th><th>显示用途</th><th>最高等级</th><th>需求分组</th><th>默认升级模式</th><th>默认属性贡献</th></tr></thead><tbody><tr><td><code>main</code></td><td>主等级 / 总成长</td><td>100</td><td><code>main</code></td><td>自动 + 手动</td><td><code>attribute_power = %level% * 0.5</code></td></tr><tr><td><code>combat</code></td><td>原版与 MythicMobs 战斗</td><td>80</td><td><code>combat</code></td><td>自动 + 手动</td><td><code>physical_attack</code>、<code>physical_crit_rate</code></td></tr><tr><td><code>mining</code></td><td>挖矿</td><td>60</td><td><code>mining</code></td><td>手动，默认不自动</td><td><code>mining_power = %level% * 0.2</code></td></tr><tr><td><code>logging</code></td><td>砍伐原木</td><td>60</td><td><code>logging</code></td><td>自动 + 手动</td><td>默认关闭</td></tr><tr><td><code>gathering</code></td><td>采集植物/杂物</td><td>60</td><td><code>gathering</code></td><td>自动 + 手动</td><td>默认关闭</td></tr><tr><td><code>farming</code></td><td>成熟作物收获</td><td>60</td><td><code>farming</code></td><td>自动 + 手动</td><td>默认关闭</td></tr><tr><td><code>fishing</code></td><td>钓鱼</td><td>60</td><td><code>fishing</code></td><td>自动 + 手动</td><td>默认关闭</td></tr><tr><td><code>taming</code></td><td>驯养实体</td><td>60</td><td><code>taming</code></td><td>自动 + 手动</td><td>默认关闭</td></tr><tr><td><code>crafting</code></td><td>合成物品</td><td>60</td><td><code>crafting</code></td><td>自动 + 手动</td><td>默认关闭</td></tr><tr><td><code>brewing</code></td><td>炼药台完成炼药</td><td>60</td><td><code>brewing</code></td><td>自动 + 手动</td><td>默认关闭</td></tr><tr><td><code>smelting</code></td><td>熔炉提取产物</td><td>60</td><td><code>smelting</code></td><td>自动 + 手动</td><td>默认关闭</td></tr><tr><td><code>cooking</code></td><td>给烹饪玩法预留</td><td>60</td><td><code>cooking</code></td><td>自动 + 手动</td><td>默认关闭</td></tr><tr><td><code>forging</code></td><td>给锻造玩法预留</td><td>60</td><td><code>forging</code></td><td>自动 + 手动</td><td>默认关闭</td></tr></tbody></table><p>默认类型只是示例和开箱模板。你可以新增、删除、禁用或改名 <code>types/*.yml</code> 中的类型，但命令、Placeholder、来源规则和 Action 中引用的 <code>type</code> 必须保持一致。</p><h2 id="基础工作流" tabindex="-1">基础工作流 <a class="header-anchor" href="#基础工作流" aria-label="Permalink to “基础工作流”">​</a></h2><ol><li>安装并启动 <code>EmakiCoreLib</code> 与 <code>EmakiLevel</code>。</li><li>查看 <code>plugins/EmakiLevel/types/</code>，确认需要保留哪些等级类型。</li><li>在 <code>requirements.yml</code> 中设置主线和职业等级的经验曲线。</li><li>在 <code>sources/*.yml</code> 中配置哪些行为给予哪些类型的经验。</li><li>如果需要手动升级消耗，编辑对应 <code>types/&lt;type&gt;.yml &gt; upgrade.cost</code>。</li><li>如果安装了 EmakiAttribute，在 <code>types/&lt;type&gt;.yml &gt; attributes.values</code> 中配置等级属性公式。</li><li>执行 <code>/elv reload</code> 重载配置。</li><li>使用 <code>/elv info</code>、<code>/elv debug requirement &lt;type&gt; &lt;level&gt;</code> 和 PlaceholderAPI 检查结果。</li></ol><h2 id="数据与升级行为概览" tabindex="-1">数据与升级行为概览 <a class="header-anchor" href="#数据与升级行为概览" aria-label="Permalink to “数据与升级行为概览”">​</a></h2><p>玩家数据示例：</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">schema_version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">uuid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;00000000-0000-0000-0000-000000000000&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PlayerName&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">levels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    exp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    total_exp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    updated_at</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1730000000000</span></span></code></pre></div><p>升级时，插件会按如下顺序处理：</p><ol><li>找到等级类型并确认启用。</li><li>增加当前等级经验 <code>exp</code> 和总经验 <code>total_exp</code>。</li><li>执行 <code>upgrade.actions.gain</code>。</li><li>如果允许自动升级，按 <code>level.max_auto_upgrade_steps</code> 限制循环尝试升级。</li><li>每次升级检查需求经验、最高等级、手动/自动开关、经济消耗和材料消耗。</li><li>升级成功后扣除需求经验、提升等级、发放奖励、执行 <code>upgrade.actions.success</code>。</li><li>升级失败时执行 <code>upgrade.actions.failure</code>，并把 <code>failure_reason</code> 放入动作上下文。</li><li>同步 PDC，并在 EmakiAttribute 可用时刷新属性贡献。</li></ol><h2 id="文档入口" tabindex="-1">文档入口 <a class="header-anchor" href="#文档入口" aria-label="Permalink to “文档入口”">​</a></h2><ul><li><a href="./commands.html">命令与权限</a>：玩家和管理员命令、权限节点、示例。</li><li><a href="./placeholders.html">PlaceholderAPI 占位符</a>：所有 <code>%emakilevel_*%</code> 变量和排行榜占位符。</li><li><a href="./configuration.html">配置详解</a>：主配置、等级类型、需求曲线、升级消耗、PDC 与属性贡献。</li><li><a href="./sources.html">经验来源</a>：<code>sources/*.yml</code> 触发器、匹配字段、公式变量和防刷行为。</li><li><a href="./mythic.html">MythicMobs 集成</a>：MythicMob 击杀经验与自定义 Drop。</li><li><a href="./corelib-actions.html">CoreLib 动作</a>：EmakiLevel 注册到 CoreLib ActionRegistry 的动作与参数。</li><li><a href="./api.html">API 与集成</a>：开发者 API、CoreLib Action、静态门面与 Provider 接入。</li><li><a href="./events.html">事件 API</a>：<code>emaki.jiuwu.craft.level.api.event</code> 中的 Bukkit 事件与可取消性。</li></ul>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};